/** Decorative art generated by `tools/build-art.mjs`. */
const ART = {
  crest: require('../../../assets/media/art/crest.png'),
  avatarFrame: require('../../../assets/media/art/avatar-frame.png'),
  wingHeart: require('../../../assets/media/art/wing-heart.png'),
  clouds: require('../../../assets/media/art/clouds.png'),
} as const;

export type ArtName = keyof typeof ART;

export type MediaFolder = 'portraits' | 'covers' | 'posts' | 'rooms';

/**
 * Resolves an image reference to something `expo-image` can render: a bundled
 * asset id for registry entries, a remote source for anything else.
 */
export function imageSource(ref?: string): ImageSource | number | undefined {
  if (!ref) {
    return undefined;
  }
  return IMAGES[ref] ?? { uri: ref };
}

/** Builds the reference a fixture stores. Keeps the scheme in one place. */
export function mediaRef(folder: MediaFolder, name: string): string {
  return `asset:media/${folder}/${name}.jpg`;
}

export function artSource(name: ArtName): number {
  return ART[name];
}
